  parts=[]; cur=''; quote=None
  for ch in body+',':
   if ch in "\"'" and (quote is None or quote==ch): quote=None if quote else ch
   if ch==',' and quote is None: parts.append(cur);cur=''
   else: cur+=ch
  return [scalar(x) for x in parts]
 if s[0:1] in "\"'" and s[-1:]==s[0]: return s[1:-1]
 if s in ('null','Null','NULL','~'):return None
 if s.lower() in ('true','false'):return s.lower()=='true'
 if s.startswith('[') or s.startswith('{'):
  try:return json.loads(s)
